// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "https://github.com/OpenZeppelin/openzeppelin-contracts/blob/v4.8.0/contracts/access/Ownable.sol";
import "https://github.com/OpenZeppelin/openzeppelin-contracts/blob/v4.8.0/contracts/security/Pausable.sol";
import "https://github.com/OpenZeppelin/openzeppelin-contracts/blob/v4.8.0/contracts/utils/Context.sol";

/// @title White Label B2C Contract
/// @author [Your Name]
/// @notice This contract implements a white-label B2C transaction system
/// @dev This contract provides basic functionality for managing products and orders
contract WhiteLabelB2CContract is Ownable, Pausable {
    struct Product {
        string name;
        string description;
        uint256 price;
        uint256 stock;
        bool active;
    }

    struct Order {
        address customer;
        uint256 productId;
        uint256 quantity;
        uint256 timestamp;
        bool fulfilled;
    }

    mapping(uint256 => Product) public products;
    mapping(uint256 => Order) public orders;
    uint256 public productCount;
    uint256 public orderCount;

    /// @notice Emitted when a new product is created
    /// @param productId The ID of the newly created product
    /// @param name The name of the product
    /// @param description The description of the product
    /// @param price The price of the product
    /// @param stock The initial stock of the product
    event ProductCreated(
        uint256 indexed productId,
        string name,
        string description,
        uint256 price,
        uint256 stock
    );

    /// @notice Emitted when a product is updated
    /// @param productId The ID of the updated product
    /// @param name The new name of the product
    /// @param description The new description of the product
    /// @param price The new price of the product
    /// @param stock The new stock of the product
    event ProductUpdated(
        uint256 indexed productId,
        string name,
        string description,
        uint256 price,
        uint256 stock
    );

    /// @notice Emitted when a product is removed
    /// @param productId The ID of the removed product
    event ProductRemoved(uint256 indexed productId);

    /// @notice Emitted when a new order is placed
    /// @param orderId The ID of the newly placed order
    /// @param customer The address of the customer who placed the order
    /// @param productId The ID of the product ordered
    /// @param quantity The quantity of the product ordered
    event OrderPlaced(
        uint256 indexed orderId,
        address indexed customer,
        uint256 indexed productId,
        uint256 quantity
    );

    /// @notice Emitted when an order is fulfilled
    /// @param orderId The ID of the fulfilled order
    event OrderFulfilled(uint256 indexed orderId);

    /// @notice Creates a new product
    /// @param name The name of the product
    /// @param description The description of the product
    /// @param price The price of the product
    /// @param stock The initial stock of the product
    /// @return The ID of the newly created product
    function createProduct(
        string memory name,
        string memory description,
        uint256 price,
        uint256 stock
    ) public onlyOwner notPaused returns (uint256) {
        require(price > 0, "Price must be greater than zero");
        require(stock >= 0, "Stock cannot be negative");

        productCount++;
        uint256 productId = productCount;
        products[productId] = Product(
            name,
            description,
            price,
            stock,
            true
        );

        emit ProductCreated(productId, name, description, price, stock);
        return productId;
    }

    /// @notice Updates an existing product
    /// @param productId The ID of the product to update
    /// @param name The new name of the product
    /// @param description The new description of the product
    /// @param price The new price of the product
    /// @param stock The new stock of the product
    function updateProduct(
        uint256 productId,
        string memory name,
        string memory description,
        uint256 price,
        uint256 stock
    ) public onlyOwner notPaused {
        require(productId <= productCount, "Product ID does not exist");
        require(price > 0, "Price must be greater than zero");
        require(stock >= 0, "Stock cannot be negative");

        Product storage product = products[productId];
        product.name = name;
        product.description = description;
        product.price = price;
        product.stock = stock;

        emit ProductUpdated(productId, name, description, price, stock);
    }

    /// @notice Removes a product
    /// @param productId The ID of the product to remove
    function removeProduct(uint256 productId) public onlyOwner notPaused {
        require(productId <= productCount, "Product ID does not exist");

        delete products[productId];
        emit ProductRemoved(productId);
    }

    /// @notice Places a new order
    /// @param productId The ID of the product to order
    /// @param quantity The quantity to order
    /// @return The ID of the newly placed order
    function placeOrder(uint256 productId, uint256 quantity)
        public
        notPaused
        returns (uint256)
    {
        require(productId <= productCount, "Product ID does not exist");
        require(quantity > 0, "Quantity must be greater than zero");

        Product storage product = products[productId];
        require(product.active, "Product is not active");
        require(product.stock >= quantity, "Not enough stock available");

        orderCount++;
        uint256 orderId = orderCount;
        orders[orderId] = Order(
            msg.sender,
            productId,
            quantity,
            block.timestamp,
            false
        );

        // Update stock
        product.stock -= quantity;

        emit OrderPlaced(orderId, msg.sender, productId, quantity);
        return orderId;
    }

    /// @notice Fulfills an order
    /// @param orderId The ID of the order to fulfill
    function fulfillOrder(uint256 orderId) public onlyOwner notPaused {
        require(orderId <= orderCount, "Order ID does not exist");
        require(!orders[orderId].fulfilled, "Order already fulfilled");

        orders[orderId].fulfilled = true;
        emit OrderFulfilled(orderId);
    }

    /// @notice Transfers ownership of the contract
    /// @param newOwner The new owner's address
    function transferOwnership(address newOwner) public onlyOwner {
        _transferOwnership(newOwner);
    }

    /**
     * @dev This empty reserved space is put in place to allow future versions to add new
     * variables without shifting down storage in the inheritance chain.
     * See https://docs.openzeppelin.com/contracts/4.x/upgradeable#storage_gaps
     */
    uint256[50] private __gap;
}
